const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const clone = value => structuredClone(value);
const sample = () => ({id:null,name:'Atelier — sample',brief:'An independent creative studio. Thoughtful design, editorial typography, and a warm, considered palette.',source:null,variants:seedVariants('Independent creative studio',null),activeVariant:'variant-editorial',revision:0});
const fields = p => ({name:p.name,brief:p.brief,source:p.source,variants:p.variants,activeVariant:p.activeVariant});
const fingerprint = p => JSON.stringify(fields(p));
const sessions = new Map();
const state = {config:null,user:null,usage:null,projects:[],current:null,pageId:null,sectionId:null,device:'desktop',tab:'design',busy:false,dragId:null,versionsToken:0};
function session(project, saved=true) {return {project:clone(project),baseline:saved?fingerprint(project):'',undo:[],redo:[],messages:[],pageId:null,sectionId:null,lastEdit:null,sampleDesign:!project.id};}
