 const grid=node('div','comparison-grid');project().variants.forEach(v=>{const card=node('article','comparison-card');const active=v.id===variant().id;card.classList.toggle('active',active);card.append(node('h3',null,v.name.split('/')[0].trim()),miniature(v.document,`${v.name} comparison preview`),paragraph(`${v.document.pages.length} pages · ${v.document.theme.font} typography`));const choose=writeButton(active?'Selected design':'Use this design','button '+(active?'button-quiet':'button-purple'),()=>{chooseVariant(v.id);closeModal();});choose.setAttribute('aria-pressed',String(active));card.append(choose);grid.append(card);});body.append(grid,paragraph($('#directionsStatus').textContent,'modal-help'));
