function setTab(tab){state.tab=tab;$$('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});for(const name of ['design','assistant','history'])$(`#panel-${name}`).hidden=name!==tab;if(tab==='history')loadVersions();}
