async function saveInternal(){if(!project().id)throw new Error('This is an anonymous sample. Create a server project to save your work.');if(!dirty())return project();const payload=clone(project());payload.variants=payload.variants.map(v=>({...v,document:validateDocument(v.document)}));const {project:p}=await api(`/api/projects/${encodeURIComponent(payload.id)}`,{method:'PUT',body:payload});receive(p,{preserveHistory:true});return p;}
