  form.querySelector('.modal-error')?.remove();form.setAttribute('aria-busy','true');setBusy(true,input.mode==='url'?'Importing content & creating project…':'Creating project…');submit.textContent=draft.createdProject?'Saving project…':input.mode==='url'?'Importing & creating…':'Creating project…';status.textContent=draft.createdProject?'Saving the retained project draft.':input.mode==='url'?'Importing public-page content, then creating your project.':'Creating your project with labeled sample directions.';
