function renameDialog(){if(state.busy)return;const body=modal('A name to make it yours.','PROJECT');const form=node('form');const input=modalField(form,'Project name',{value:project().name,max:100});submitForm(form,'Rename project',async()=>{mutate(p=>p.name=input.value.trim());render();if(project().id)await run('Renaming…',async()=>{await saveInternal();$('#modal').close();toast('Project renamed.');});else closeModal();});body.append(form);}
