function showSource(){const source=project().source;if(!source)return;const body=modal(source.title||'Imported source','SOURCE & PROVENANCE');body.append(paragraph('Public static HTML was fetched and its readable text extracted. Scripts were not executed. This is source material, not an AI redesign.'));const url=safeLink(source.url);if(url){const meta=node('div','source-meta');const a=node('a',null,url);a.href=url;a.target='_blank';a.rel='noopener noreferrer';meta.append(a);body.append(meta);}if(source.description)body.append(paragraph(source.description));const text=node('div','source-preview',source.text||'No readable text was extracted.');text.tabIndex=0;body.append(text);if(source.headings?.length){body.append(node('h3',null,'Extracted headings'));const list=node('ul','source-meta');source.headings.forEach(h=>list.append(node('li',null,typeof h==='string'?h:h.text||h.title||'')));body.append(list);}body.append(paragraph(`${source.links?.length||0} links · ${source.images?.length||0} image references. Import preserves content provenance; it does not copy another website’s design.`, 'modal-help'));body.append(button('Remove attached source','button button-quiet full-width',()=>{mutate(p=>p.source=null);render();closeModal();}));}
function importDialog(){if(!project().id){if(!startDraft)startDraft={mode:'url',name:'My studio',brief:project().brief||'',url:'',error:'',copyFields:clone(fields(project()))};createProjectDialog(true);return;}if(!state.user){authDialog();return;}const body=modal('Import website content','URL IMPORT');body.append(paragraph('Import readable content from a public webpage, then use it as context for your own design. Private pages and sites that require scripts may not yield useful content.'));const form=node('form');const url=modalField(form,'Public website URL',{type:'url',max:2048,value:project().source?.url||''});submitForm(form,'Extract content',async()=>{const input=validateStartInput({mode:'url',name:project().name,brief:'',url:url.value});await run('Importing source…',async()=>{const {source}=await api('/api/import',{method:'POST',body:{url:input.url}});if(!source||typeof source.text!=='string')throw new Error('The import API returned no readable source.');const before=clone(fields(project()));project().source=source;state.current.undo.push(before);state.current.redo=[];state.current.lastEdit=null;render();$('#modal').close();showSource();toast('Source attached to your draft. Save to persist it.');});});body.append(form);}
async function generate(){if(!state.user){authDialog();return;}if(!project().id){createProjectDialog(true);return;}if(!state.config?.aiConfigured){modelDialog();return;}if(!project().brief.trim()){notice('Add a design brief before generating.',true);$('#briefInput').focus();return;}confirmDialog('Generate three new directions?','The model will replace this project’s current variants. Existing saved snapshots remain available.',()=>run('Generating three directions…',async()=>{await saveInternal();const p=project();const {project:next}=await api(`/api/projects/${encodeURIComponent(p.id)}/generate`,{method:'POST',body:{brief:p.brief,source:p.source,revision:p.revision}});if(next.variants?.length!==3)throw new Error('The generation API did not return three variants.');receive(next,{sampleDesign:false});toast('Three model-generated directions saved to your project.');}));}
